inbound.set-body:
@{
            var body = context.Request.Body.As(preserveContent: true);
            if (((string)body["model"] ?? "").StartsWith("databricks-claude")) {
                body.Remove("top_p");
            }
            return body.ToString(Newtonsoft.Json.Formatting.None);
        }

when.set-body:
@{
                    var lines = context.Response.Body.As().Split('\n');
                    for (var i = 0; i < lines.Length; i++) {
                        var line = lines[i].TrimEnd('\r');
                        if (!line.StartsWith("data:")) { continue; }
                        var json = line.Substring(5).Trim();
                        if (!json.StartsWith("{")) { continue; }
                        var chunk = JObject.Parse(json);
                        var usage = chunk["usage"] as JObject;
                        if (usage != null) {
                            if (usage["completion_tokens"] == null || usage["completion_tokens"].Type == JTokenType.Null) {
                                chunk.Remove("usage");
                            } else {
                                chunk["usage"] = new JObject(
                                    new JProperty("prompt_tokens", usage["prompt_tokens"]),
                                    new JProperty("completion_tokens", usage["completion_tokens"]),
                                    new JProperty("total_tokens", usage["total_tokens"]));
                            }
                        }
                        lines[i] = "data: " + chunk.ToString(Newtonsoft.Json.Formatting.None);
                    }
                    return string.Join("\n", lines);
                }
